int main() {
    std::vector<int> v{5, 3, 9};
    v.push_back(1);
    v.insert(v.begin(), 7);          // вставка в начало — сдвигает всё, O(n)
    v.pop_back();

    std::cout << "размер: " << v.size() << ", ёмкость: " << v.capacity() << "\n";
    for (int x : v) std::cout << x << ' ';
    std::cout << "\n";

    std::cout << "первый: " << v.front() << ", последний: " << v.back() << "\n";
    std::cout << "по индексу [1]: " << v[1] << "\n";

    // at() проверяет границы, [] — нет
    std::cout << "at(0): " << v.at(0) << "\n";

    // reserve заранее: одно выделение вместо цепочки удвоений
    std::vector<std::string> names;
    names.reserve(3);
    names.push_back("aziz");
    names.push_back("bek");
    names.push_back("dilnoza");
    for (const std::string& n : names) std::cout << n << ' ';
    std::cout << "\n";

    std::vector<std::vector<int>> grid(2, std::vector<int>(3, 0));
    grid[1][2] = 42;
    std::cout << "матрица[1][2] = " << grid[1][2] << "\n";
    return 0;
}

#include <iostream>
#include <map>
#include <unordered_map>
#include <set>
#include <string>

int main() {
    std::map<std::string, int> prices{{"кофе", 25000}, {"чай", 15000}};
    prices["сок"] = 18000;
    prices["чай"] = 16000;              // перезапись

    // map всегда обходится по возрастанию ключа
    for (const auto& [name, price] : prices)
        std::cout << name << " = " << price << "\n";

    // find возвращает итератор; end() значит «не нашли»
    auto it = prices.find("кофе");
    if (it != prices.end()) std::cout << "нашли кофе: " << it->second << "\n";
    std::cout << "есть пиво? " << prices.count("пиво") << "\n";

    // ОСТОРОЖНО: обращение через [] к отсутствующему ключу СОЗДАЁТ его
    std::cout << "размер до: " << prices.size() << "\n";
    int beer = prices["пиво"];
    std::cout << "пиво = " << beer << ", размер после: " << prices.size() << "\n";

    std::set<int> uniq{5, 2, 9, 2, 5};
    std::cout << "уникальных: " << uniq.size() << " -> ";
    for (int x : uniq) std::cout << x << ' ';
    std::cout << "\n";

    std::unordered_map<char, int> freq;
    for (char c : std::string("abracadabra")) freq[c]++;
    std::cout << "a встречается " << freq['a'] << " раз\n";
    return 0;
}

