#include <iostream>
#include <vector>
#include <deque>
#include <map>
#include <string>

int main() {
    // задача: посчитать заказы по городам и вывести по алфавиту
    std::vector<std::pair<std::string, int>> orders{
        {"Ташкент", 250}, {"Бухара", 100}, {"Ташкент", 400}, {"Самарканд", 180},
    };

    std::map<std::string, int> totals;      // map — потому что нужен алфавит
    for (const auto& [city, amount] : orders)
        totals[city] += amount;             // здесь [] уместен: создаём ноль и прибавляем

    for (const auto& [city, total] : totals)
        std::cout << city << ": " << total << "\n";

    // deque — когда добавляем с обоих концов
    std::deque<std::string> queue;
    queue.push_back("второй");
    queue.push_front("первый");
    queue.push_back("третий");
    std::cout << "очередь: ";
    for (const auto& s : queue) std::cout << s << ' ';
    std::cout << "\nвзяли спереди: " << queue.front() << "\n";

    return 0;
}

