#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <algorithm>

int main() {
    std::vector<std::pair<std::string, int>> purchases{
        {"aziz", 250}, {"bek", 410}, {"aziz", 400}, {"dilnoza", 250}, {"bek", 240},
    };

    std::map<std::string, int> totals;
    for (const auto& [name, amount] : purchases)
        totals[name] += amount;

    // map нельзя отсортировать по значению — переливаем в vector
    std::vector<std::pair<std::string, int>> rows(totals.begin(), totals.end());
    std::sort(rows.begin(), rows.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;   // по сумме убывая
        return a.first < b.first;                               // при равенстве — по имени
    });

    for (size_t i = 0; i < rows.size(); i++)
        std::cout << (i + 1) << ". " << rows[i].first << ' ' << rows[i].second << "\n";
    return 0;
}
